// Ported 2026-11-20 from WPI-HPRC/pid-tuner include/ControlMath.h (branch
// feat/serial-pid-tuner, commit d7b3440). Canards-Rocket carries the same code
// in src/canards/pid_tuner/ControlMath.h.
//
// The logic must stay IDENTICAL to pid-tuner, so that servo gains and
// calibration from the bench stay valid in flight. Nothing below this comment
// differs from the original. Do not edit this file on its own: change the
// tuner, then copy again.
//
// Note: clamp() passes NaN straight through. ServoControl checks for that.
#pragma once

#include <cmath>

namespace tuning {

inline float clamp(float value, float minimum, float maximum) {
    if (value < minimum) {
        return minimum;
    }
    if (value > maximum) {
        return maximum;
    }
    return value;
}

/** Signed shortest displacement, including the encoder's 0/360 degree wrap. */
inline float wrappedError(float target, float measured) {
    return std::remainder(target - measured, 360.f);
}

} // namespace tuning
